<?php declare(strict_types=1);namespace FMonitor2\Otiz;use yii\db\Connection;
final class MariaDbOtizCalculationRegister
{
 public function __construct(private Connection$db,private string$p){}
 public function read(string$filter,string$year,int$page,int$size=25):array{$where=["c.status<>'deleted'"];$params=[];if($filter==='drafts')$where[]="c.status='draft'";elseif($filter==='history')$where[]="EXISTS(SELECT 1 FROM `{$this->p}fm2_otiz_payment_facts` p WHERE p.calculation_id=c.id)";elseif($filter==='waiting')$where[]="c.status='accepted' AND EXISTS(SELECT 1 FROM `{$this->p}fm2_otiz_recipient_obligations` o WHERE o.calculation_id=c.id) AND NOT EXISTS(SELECT 1 FROM `{$this->p}fm2_otiz_payment_facts` p WHERE p.calculation_id=c.id AND NOT EXISTS(SELECT 1 FROM `{$this->p}fm2_otiz_payment_reversals` r WHERE r.payment_id=p.id))";if(preg_match('/^\d{4}$/D',$year)){$where[]='YEAR(c.report_date)=:year';$params[':year']=(int)$year;}$predicate=implode(' AND ',$where);$total=(int)$this->db->createCommand("SELECT COUNT(*) FROM `{$this->p}fm2_otiz_calculation_revisions` c WHERE {$predicate}",$params)->queryScalar();$pages=max(1,(int)ceil($total/$size));if($page<1||$page>$pages)throw new \DomainException('REGISTER_PAGE_NOT_FOUND');$offset=($page-1)*$size;$rows=$this->db->createCommand("SELECT c.id,c.revision,c.status,c.report_date,c.projection_json,(SELECT COALESCE(SUM(p.amount_cents),0) FROM `{$this->p}fm2_otiz_payment_facts` p WHERE p.calculation_id=c.id AND NOT EXISTS(SELECT 1 FROM `{$this->p}fm2_otiz_payment_reversals` rv WHERE rv.payment_id=p.id)) paid_cents FROM `{$this->p}fm2_otiz_calculation_revisions` c WHERE {$predicate} ORDER BY c.id DESC LIMIT {$size} OFFSET {$offset}",$params)->queryAll();return compact('rows','page','pages','total')+['pageSize'=>$size];}
}
